DO $fixture$
DECLARE
  v_snapshot jsonb;
  v_tokens jsonb;
  v_scope_sha text;
  v_accept_sha text;
  v_context_sha text;
  v_sem_sha text;
BEGIN
  SELECT jsonb_agg(jsonb_build_object(
      'version_id',identity_version_id,'sha256',value_sha256,'role',role)
      ORDER BY identity_version_id)
  INTO v_snapshot
  FROM saly.creative_context_tokens WHERE context_set_id=9006;

  IF jsonb_array_length(v_snapshot)<>109 THEN
    RAISE EXCEPTION 'F3A_REAL_FIXTURE_TOKEN_COUNT';
  END IF;
  IF encode(extensions.digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex')
     <> 'f4bc5bf450bdfb220191305c134121c266cbd4ff14d8a69910085e4b211914aa'
  THEN RAISE EXCEPTION 'F3A_REAL_FIXTURE_SNAPSHOT_SHA'; END IF;

  SELECT jsonb_agg(jsonb_build_object(
      'code',e.code,'role',t.role,'version_id',v.id,'value_json',v.value_json,
      'value_sha256',t.value_sha256) ORDER BY e.code)
  INTO v_tokens
  FROM saly.creative_context_tokens t
  JOIN saly.identity_versions v ON v.id=t.identity_version_id
  JOIN saly.identity_elements e ON e.id=v.element_id
  WHERE t.context_set_id=9006;

  IF encode(extensions.digest(convert_to(v_tokens::text,'UTF8'),'sha256'),'hex')
     <> '6b5f5eea5fe000441a7b774e5e02ec19709da6dd2603e8d6feebb88afc6c22fd'
  THEN RAISE EXCEPTION 'F3A_REAL_FIXTURE_FULL_TOKEN_SHA'; END IF;

  SELECT
    encode(extensions.digest(convert_to(o.scope_json::text,'UTF8'),'sha256'),'hex'),
    encode(extensions.digest(convert_to(i.acceptance_json::text,'UTF8'),'sha256'),'hex'),
    encode(extensions.digest(convert_to(i.context_json::text,'UTF8'),'sha256'),'hex'),
    encode(extensions.digest(convert_to((i.acceptance_json#>'{semantic_qa,original_messages}')::text,'UTF8'),'sha256'),'hex')
  INTO v_scope_sha,v_accept_sha,v_context_sha,v_sem_sha
  FROM saly.creative_orders o JOIN saly.creative_order_items i ON i.order_id=o.id
  WHERE o.id=9323 AND i.id=9327;

  IF v_scope_sha<>'17b676fb83fd416c5fbcdb6694c3f0d6c398f0b4d9ed3c4a6b654a3510614893'
  THEN RAISE EXCEPTION 'F3A_REAL_FIXTURE_SCOPE_SHA'; END IF;
  IF v_accept_sha<>'9770380c7e38e851a00bece50f707796022e20cd336c91c179448e6edbf31c03'
  THEN RAISE EXCEPTION 'F3A_REAL_FIXTURE_ACCEPTANCE_SHA'; END IF;
  IF v_context_sha<>'d8c3c2fcc33ac31346cb05610745bc8840b1bb82105d9eb994da821889490bf0'
  THEN RAISE EXCEPTION 'F3A_REAL_FIXTURE_ITEM_CONTEXT_SHA'; END IF;
  IF v_sem_sha<>'78160d6438c2908d469e9ece838b0a14b57eb317b1215cfb702e507e7bbb1f40'
  THEN RAISE EXCEPTION 'F3A_REAL_FIXTURE_SEMANTIC_ORIGINAL_SHA'; END IF;

  IF (SELECT context_set_id FROM saly.creative_orders WHERE id=9323)<>9006
     OR EXISTS (SELECT 1 FROM saly.creative_orders WHERE id=23)
     OR EXISTS (SELECT 1 FROM saly.creative_order_items WHERE id=27)
  THEN RAISE EXCEPTION 'F3A_REAL_FIXTURE_PROTECTED_ID_LEAK'; END IF;

  RAISE NOTICE 'F3A_REAL_FIXTURE|PASS|order=9323|item=9327|tokens=109';
END
$fixture$;

COMMIT;
